function splitCSVLine(line) {
  const out = [];
  let current = "";
  let inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (ch === '"' && line[i + 1] === '"') {
      current += '"';
      i++;
    } else if (ch === '"') {
      inQuotes = !inQuotes;
    } else if (ch === "," && !inQuotes) {
      out.push(current);
      current = "";
    } else {
      current += ch;
    }
  }
  out.push(current);
  return out;
}

function parseCSV(text) {
  const lines = text.trim().split(/\r?\n/);
  if (!lines.length) return [];
  const headers = splitCSVLine(lines[0]);
  return lines.slice(1).filter(Boolean).map(line => {
    const values = splitCSVLine(line);
    const obj = {};
    headers.forEach((h, i) => obj[h] = values[i] ?? "");
    return obj;
  });

  if (renderedSections === 0) {
    app.innerHTML = '<div class="empty">No bosses or items match the current filters.</div>';
  }
}

async function loadData() {
  const loot = await fetch("data/loot.json").then(r => r.json());
  state.loot = loot;

  try {
    const csvText = await fetch(COMMENTARY_SOURCE_URL).then(r => r.text());
    const rows = parseCSV(csvText);
    rows.forEach(row => state.commentaryById.set(String(row.item_id), row));
  } catch (err) {
    console.warn("Commentary source could not be loaded:", err);
  }
}

function mergeItem(item, raidName, bossName) {
  const c = state.commentaryById.get(String(item.item_id)) || {};
  return {
    ...item,
    raid: raidName,
    boss: bossName,
    p1: c.p1 || "",
    p2: c.p2 || "",
    p3: c.p3 || "",
    notes: c.notes || "",
    tags: c.tags || ""
  };
}


function normalizeTextForLookup(value) {
  return String(value ?? "")
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[Ææ]/g, "ae")
    .trim()
    .toLowerCase();
}

function escapeRegex(value) {
  return String(value).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function resolvePlayerSpec(text) {
  if (!text) return null;
  const hay = normalizeTextForLookup(text);

  for (const [name, spec] of Object.entries(playerMainSpecs)) {
    const normalizedName = normalizeTextForLookup(name);
    const pattern = new RegExp(`(^|[^a-z0-9])${escapeRegex(normalizedName)}([^a-z0-9]|$)`, "i");
    if (pattern.test(hay)) return spec;
  }

  return null;
}

function expandSpecAlias(text) {
  if (!text) return text;
  const lower = normalizeTextForLookup(text);

  if (lower.includes("beast mastery")) return "Beast Master Hunter";
  if (lower.includes("enhance shaman") || lower.includes("enhancement")) return "Enhancement Shaman";
  if (lower.includes("retrebution") || lower.includes("retribution") || lower.includes("ret paladin")) return "Retribution Paladin";

  if (
    lower.includes("boom chicken") ||
    lower.includes("boomie") ||
    lower.includes("chicken") ||
    lower.includes("moomkin") ||
    lower.includes("moonkin") ||
    lower.includes("boomkin")
  ) return "Boom Chicken";

  if (
    lower.includes("tree") ||
    lower.includes("restoration druid") ||
    lower.includes("resto druid")
  ) return "Restoration Druid";

  if (lower.includes("elemental") && !lower.includes("shaman")) return "Elemental Shaman";
  if (lower.includes("survival") && !lower.includes("hunter")) return "Survival Hunter";

  return text;
}

function resolveSpecLabel(text) {
  if (!text) return null;

  const playerSpec = resolvePlayerSpec(text);
  const searchableText = expandSpecAlias(playerSpec || text);

  const labels = Object.keys(specToClass).sort((a, b) => b.length - a.length);
  const lower = searchableText.toLowerCase();
  for (const label of labels) {
    if (lower.includes(label.toLowerCase())) return label;
  }
  return null;
}

function resolveClass(text) {
  const spec = resolveSpecLabel(text);
  if (!spec) return null;
  return specToClass[spec] || null;
}

function resolveSpriteX(text) {
  const spec = resolveSpecLabel(text);
  if (!spec) return null;
  const tileNum = spriteTileNum[spec];
  if (!tileNum) return null;
  return rightTileToLeftPx(tileNum);
}

function iconHtml(text) {
  const x = resolveSpriteX(text);
  if (x === null || !spriteIcons[x]) return "";
  return `<img class="class-icon" src="${spriteIcons[x]}" alt="">`;
}

function priorityBadge(label, prefix) {
  if (!label) return "";
  const inferredSpec = resolvePlayerSpec(label);
  const cls = resolveClass(label);
  if (!cls || !classStyles[cls]) {
    return `<span class="badge">${prefix}: ${label}</span>`;
  }
  const style = classStyles[cls];
  const textColor = cls === "Priest" ? "#f5f7fb" : style.color;
  const bg = style.color + "22";
  const specLine = inferredSpec ? `<span class="badge-spec">${inferredSpec}</span>` : "";
  return `
    <span class="badge class-badge" style="border-color:${style.color}; color:${textColor}; background:${bg};">
      ${iconHtml(label)}
      <span class="badge-text"><span>${prefix}: ${label}</span>${specLine}</span>
    </span>
  `;
}


function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function cleanTagText(tags) {
  if (!tags || !String(tags).trim()) return "";
  return String(tags)
    .split(",")
    .map(tag => tag.trim())
    .filter(Boolean)
    .join(" • ");
}

function cardTagTooltipHtml(tags) {
  const cleanTags = cleanTagText(tags);
  if (!cleanTags) return "";
  return `<div class="tag-tooltip">Tags: ${escapeHtml(cleanTags)}</div>`;
}

function makeTabs() {
  const tabs = document.getElementById("raidTabs");
  tabs.innerHTML = "";
  state.loot.raids.forEach(raid => {
    const btn = document.createElement("button");
    btn.className = "raid-tab" + (raid.id === state.activeRaid ? " active" : "");
    btn.textContent = raid.name;
    btn.onclick = () => {
      state.activeRaid = raid.id;
      makeTabs();
      render();
    };
    tabs.appendChild(btn);
  });
}

function render() {
  const app = document.getElementById("app");
  const search = document.getElementById("search").value.trim().toLowerCase();
  const bossFilter = document.getElementById("bossFilter").value.trim().toLowerCase();
  const raid = state.loot.raids.find(r => r.id === state.activeRaid);
  app.innerHTML = "";
  let renderedSections = 0;

  if (!raid) {
    app.innerHTML = '<div class="empty">No raid data found.</div>';
    return;
  }

  raid.bosses.forEach(boss => {
    const items = boss.loot
      .map(item => mergeItem(item, raid.name, boss.name))
      .filter(item => {
        const hay = [
          item.name, item.boss, item.raid, item.notes, item.p1, item.p2, item.p3, item.tags, String(item.item_id)
        ].join(" ").toLowerCase();
        if (search && !hay.includes(search)) return false;
        if (bossFilter && !item.boss.toLowerCase().includes(bossFilter)) return false;
        return true;
      });

    const section = document.createElement("section");
    section.className = "boss-section";

    const head = document.createElement("div");
    head.className = "boss-head";
    head.innerHTML = `
      <div><h2>${boss.name}</h2></div>
      <div class="meta">${items.length} visible item${items.length === 1 ? "" : "s"}</div>
    `;
    section.appendChild(head);

    head.addEventListener("click", () => {
      section.classList.toggle("open");
    });

    if (!items.length) {
      return;
    }

    const cards = document.createElement("div");
    cards.className = "cards";

    items.forEach(item => {
      const prio = [
        priorityBadge(item.p1, "P1"),
        priorityBadge(item.p2, "P2"),
        priorityBadge(item.p3, "P3")
      ].filter(Boolean).join("");

      const notes = item.notes || "No commentary yet.";
      const wowheadUrl = `https://www.wowhead.com/tbc/item=${item.item_id}`;
      const card = document.createElement("article");
      card.className = "card";
      card.innerHTML = `
        <h3>
          <a href="${wowheadUrl}"
             target="_blank"
             rel="noopener noreferrer"
             class="wowhead-link">
            ${item.name}
          </a>
        </h3>
        <div class="card-hover-zone">
          <div class="sub">${item.boss}</div>
          <div class="prio">${prio || '<span class="badge">No priority set</span>'}</div>
          <p class="notes">${notes}</p>
          <div class="itemid-wrap">
            ${cardTagTooltipHtml(item.tags)}
            <div class="itemid">Item ID: ${item.item_id}</div>
          </div>
        </div>
      `;
      cards.appendChild(card);
    });

    section.appendChild(cards);

    if (search || bossFilter) {
      section.classList.add("open");
    }
    app.appendChild(section);
    renderedSections++;
  });
}

async function init() {
  await loadData();
  makeTabs();
  render();
  document.getElementById("search").addEventListener("input", render);
  document.getElementById("bossFilter").addEventListener("input", render);
}

init();
